var (
	_ Decl = (*FuncDecl)(nil)
	_ Decl = (*ConstDecl)(nil)
	_ Decl = (*TypeDecl)(nil)
	_ Decl = (*EnumDecl)(nil)
	_ Decl = (*UnionDecl)(nil)
	_ Decl = (*AliasDecl)(nil)
	_ Decl = (*InterfaceDecl)(nil)
)

type DeclVisitor interface {
	VisitFuncDecl(n *FuncDecl)
	VisitConstDecl(n *ConstDecl)
	VisitTypeDecl(n *TypeDecl)
	VisitEnumDecl(n *EnumDecl)
	VisitUnionDecl(n *UnionDecl)
	VisitAliasDecl(n *AliasDecl)
	VisitInterfaceDecl(n *InterfaceDecl)
}

func VisitDecl(v DeclVisitor, n Decl) {
	switch n := n.(type) {
	case *FuncDecl:
		v.VisitFuncDecl(n)
		return
	case *ConstDecl:
		v.VisitConstDecl(n)
		return
	case *TypeDecl:
		v.VisitTypeDecl(n)
		return
	case *EnumDecl:
		v.VisitEnumDecl(n)
		return
	case *UnionDecl:
		v.VisitUnionDecl(n)
		return
	case *AliasDecl:
		v.VisitAliasDecl(n)
		return
	case *InterfaceDecl:
		v.VisitInterfaceDecl(n)
		return
	}
	panic(diag.Internal("unhandled Decl %T", n))
}

type DeclResultVisitor[R any] interface {
	VisitFuncDecl(n *FuncDecl) R
	VisitConstDecl(n *ConstDecl) R
	VisitTypeDecl(n *TypeDecl) R
	VisitEnumDecl(n *EnumDecl) R
	VisitUnionDecl(n *UnionDecl) R
	VisitAliasDecl(n *AliasDecl) R
	VisitInterfaceDecl(n *InterfaceDecl) R
}

func VisitDeclResult[R any](v DeclResultVisitor[R], n Decl) R {
	switch n := n.(type) {
	case *FuncDecl:
		return v.VisitFuncDecl(n)
	case *ConstDecl:
		return v.VisitConstDecl(n)
	case *TypeDecl:
		return v.VisitTypeDecl(n)
	case *EnumDecl:
		return v.VisitEnumDecl(n)
	case *UnionDecl:
		return v.VisitUnionDecl(n)
	case *AliasDecl:
		return v.VisitAliasDecl(n)
	case *InterfaceDecl:
		return v.VisitInterfaceDecl(n)
	}
	panic(diag.Internal("unhandled Decl %T", n))
}

type DeclStateVisitor[S, R any] interface {
	VisitFuncDecl(n *FuncDecl, s S) R
	VisitConstDecl(n *ConstDecl, s S) R
	VisitTypeDecl(n *TypeDecl, s S) R
	VisitEnumDecl(n *EnumDecl, s S) R
	VisitUnionDecl(n *UnionDecl, s S) R
	VisitAliasDecl(n *AliasDecl, s S) R
	VisitInterfaceDecl(n *InterfaceDecl, s S) R
}

func VisitDeclState[S, R any](v DeclStateVisitor[S, R], n Decl, s S) R {
	switch n := n.(type) {
	case *FuncDecl:
		return v.VisitFuncDecl(n, s)
	case *ConstDecl:
		return v.VisitConstDecl(n, s)
	case *TypeDecl:
		return v.VisitTypeDecl(n, s)
	case *EnumDecl:
		return v.VisitEnumDecl(n, s)
	case *UnionDecl:
		return v.VisitUnionDecl(n, s)
	case *AliasDecl:
		return v.VisitAliasDecl(n, s)
	case *InterfaceDecl:
		return v.VisitInterfaceDecl(n, s)
	}
	panic(diag.Internal("unhandled Decl %T", n))
}

var (
	_ TypeDeclNode = (*TypeDecl)(nil)
	_ TypeDeclNode = (*EnumDecl)(nil)
	_ TypeDeclNode = (*UnionDecl)(nil)
	_ TypeDeclNode = (*AliasDecl)(nil)
	_ TypeDeclNode = (*InterfaceDecl)(nil)
)

type TypeDeclNodeVisitor interface {
	VisitTypeDecl(n *TypeDecl)
	VisitEnumDecl(n *EnumDecl)
	VisitUnionDecl(n *UnionDecl)
	VisitAliasDecl(n *AliasDecl)
	VisitInterfaceDecl(n *InterfaceDecl)
}

func VisitTypeDeclNode(v TypeDeclNodeVisitor, n TypeDeclNode) {
	switch n := n.(type) {
	case *TypeDecl:
		v.VisitTypeDecl(n)
		return
	case *EnumDecl:
		v.VisitEnumDecl(n)
		return
	case *UnionDecl:
		v.VisitUnionDecl(n)
		return
	case *AliasDecl:
		v.VisitAliasDecl(n)
		return
	case *InterfaceDecl:
		v.VisitInterfaceDecl(n)
		return
	}
	panic(diag.Internal("unhandled TypeDeclNode %T", n))
}

